style.css:
@-moz-document domain("userstyles.org") {
/* Background */
    body {
        background-color: #ffe6f2 !important; /* Soft Pink */
        color: #7a3b56 !important; /* Dark Pink Text */
    }

    /* Header & Navigation */
    #header, .navbar, .nav, .menu {
        background-color: #ffb6c1 !important; /* Light Pink */
        color: #fff !important;
    }

    /* Sidebar & Panels */
    .sidebar, .panel, .widget, .box {
        background-color: #ffc1cc !important; /* Soft Pink */
        color: #7a3b56 !important;
    }

    /* Buttons */
    .button, .btn, .submit-button {
        background-color: #ff99aa !important;
        color: #fff !important;
        border-color: #ff7f9c !important;
    }

    /* Hover Effects */
    .button:hover, .btn:hover, .submit-button:hover {
        background-color: #ff8099 !important;
    }

    /* Text Fields & Inputs */
    input, textarea, select {
        background-color: #ffd9e3 !important;
        color: #000 !important;
        border-color: #ffb6c1 !important;
    }

    /* Links */
    a {
        color: #d14771 !important; /* Dark Pink */
    }

    /* Borders */
    .sidebar, .panel, .widget, .box, .btn {
        border-color: #ff7f9c !important;
    }

    /* Disable Text Selection */
    * {
        user-select: none !important;
        background-color: transparent !important;
        outline: none !important;
    }
}
